const headers=['id','kind','firstName','lastName','email','phone','dateOfBirth','cohort','username'];
export function parseAdminCSV(text){if(typeof text!=='string'||text.length>500000)throw Error('Use a CSV file smaller than 500 KB.');text=text.replace(/^\ufeff/,'');const rows=[];let row=[],cell='',quoted=false,after=false;for(let i=0;i<text.length;i++){const c=text[i];if(quoted){if(c==='"'){if(text[i+1]==='"'){cell+='"';i++;}else{quoted=false;after=true;}}else cell+=c;}else if(c==='"'){if(cell||after)throw Error('A CSV quote is misplaced.');quoted=true;}else if(c===','||c==='\n'||c==='\r'){row.push(cell);cell='';after=false;if(c!==','){if(c==='\r'&&text[i+1]==='\n')i++;if(row.some(v=>v.trim()))rows.push(row);row=[];}}else{if(after&&!/\s/.test(c))throw Error('Unexpected text after a quoted CSV field.');if(!after)cell+=c;}}if(quoted)throw Error('A quoted CSV field is unfinished.');row.push(cell);if(row.some(v=>v.trim()))rows.push(row);if(!rows.length)throw Error('The CSV file is empty.');const keys=rows.shift().map(v=>v.trim());if(new Set(keys).size!==keys.length||keys.some(k=>!headers.includes(k))||!['kind','firstName','lastName'].every(k=>keys.includes(k)))throw Error('Use the supplied template headers.');if(!rows.length||rows.length>200)throw Error('Import between 1 and 200 records at a time.');return rows.map((r,i)=>{if(r.length!==keys.length)throw Error('CSV row '+(i+2)+' has the wrong number of columns.');return Object.fromEntries(keys.map((k,n)=>[k,r[n].trim()]));});}
const cell=v=>{let s=String(v??'');if(/^\s*[=+\-@]/.test(s)||/^[\t\r\n]/.test(s))s="'"+s;return'"'+s.replaceAll('"','""')+'"';};
export const adminCSV=rows=>'\ufeff'+rows.map(r=>r.map(cell).join(',')).join('\r\n')+'\r\n';
export const adminTemplate=()=>adminCSV([headers,['','student','Example','Student','example@wist-test.invalid','','2014-05-12','7a',''],['','staff','Example','Teacher','teacher@wist-test.invalid','','1985-01-20','','example.teacher']]);
